package com.zycomic.app.net

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertNotNull
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit

/** Runs the production coordinator against deterministic offline collaborators generated by tools/test_runtime_recovery.py. */
class RuntimeImageRecoveryIntegrationTest {
    @Test
    fun `offline gate platform isolation single flight and validated alternate routing`() {
        val platforms = RuntimeRecoveryPolicy.Platform.entries
        JmRouteManager.activeImageDomain = "jm-manual.test"
        val activeSources = mapOf(
            RuntimeRecoveryPolicy.Platform.MANWA to "manwa-active.test",
            RuntimeRecoveryPolicy.Platform.JM to "jm-manual.test",
            RuntimeRecoveryPolicy.Platform.PICACG to "picacg-active.test",
        )
        RuntimeNetworkGate.setOnline(false)
        platforms.forEach { platform ->
            repeat(3) { index -> RuntimeImageRecovery.coverSample(platform, activeSources.getValue(platform), "offline-$platform-$index", failed = true) }
        }
        assertEquals(0, NetworkModule.validations.get())
        assertEquals(0, JmNetworkModule.validations.get())
        assertEquals(0, PicacgRouteManager.apiValidations.get())
        assertNull(RouteManager.switchedEndpoint)
        assertNull(JmRouteManager.switchedEndpoint)
        assertNull(PicacgRouteManager.switchedEndpoint)

        RouteManager.imgHost = "manwa-active.test"
        RouteManager.imgRewriteTarget = "manwa-active.test"
        RouteManager.candidates = listOf(DomainIp("manwa-bad.test", "10.0.0.1"), DomainIp("manwa-good.test", "10.0.0.2"))
        SpeedTester.probeResults[RouteManager.candidates[0]] = false
        SpeedTester.probeResults[RouteManager.candidates[1]] = true
        SpeedTester.blockFirstProbe = true

        JmRouteManager.manualPinned = true
        JmRouteManager.candidates = listOf(DomainIp("jm-alternate.test", "10.0.0.3"))

        PicacgRouteManager.currentImageHost = "picacg-active.test"
        PicacgRouteManager.candidates = listOf(DomainIp("picacg-good.test", "10.0.0.4"))
        PicacgSpeedTester.probeResults[PicacgRouteManager.candidates.single()] = true

        RuntimeNetworkGate.setOnline(true)
        try {
            repeat(3) { index -> RuntimeImageRecovery.coverSample(RuntimeRecoveryPolicy.Platform.MANWA, "manwa-active.test", "cover-$index", failed = true) }
            assertTrue(SpeedTester.probeEntered.await(3, TimeUnit.SECONDS), "Manwa recovery probe should start")

            // Three new distinct failures cross the policy threshold again while the first probe owns the gate.
            repeat(3) { index -> RuntimeImageRecovery.coverSample(RuntimeRecoveryPolicy.Platform.MANWA, "manwa-active.test", "second-wave-$index", failed = true) }
            assertEquals(1, SpeedTester.probeCalls.get(), "A platform must have at most one recovery flight")

            repeat(3) { index -> RuntimeImageRecovery.coverSample(RuntimeRecoveryPolicy.Platform.JM, "jm-manual.test", "jm-cover-$index", failed = true) }
            repeat(3) { index -> RuntimeImageRecovery.coverSample(RuntimeRecoveryPolicy.Platform.PICACG, "picacg-active.test", "picacg-cover-$index", failed = true) }
            assertTrue(waitUntil { PicacgRouteManager.apiValidations.get() == 1 })
            assertEquals(0, JmNetworkModule.validations.get(), "A manual route has no eligible alternatives to test")
            assertEquals(0, JmSpeedTester.probeCalls.get(), "A persisted manual JM image route must not be probed or replaced")
            assertEquals("jm-manual.test", JmRouteManager.activeImageDomain)

            SpeedTester.releaseProbe.countDown()
            assertTrue(waitUntil { RouteManager.switchedEndpoint != null && PicacgRouteManager.switchedEndpoint != null })
            assertEquals(DomainIp("manwa-good.test", "10.0.0.2"), RouteManager.switchedEndpoint)
            assertEquals(DomainIp("picacg-good.test", "10.0.0.4"), PicacgRouteManager.switchedEndpoint)
            assertEquals(1, NetworkModule.validations.get())
            assertEquals(0, JmNetworkModule.validations.get())
            assertEquals(1, PicacgRouteManager.apiValidations.get())
            assertEquals(2, SpeedTester.probeCalls.get(), "Bad candidates are rejected; only the validated alternate is committed")
            assertEquals(0, JmSpeedTester.probeCalls.get())
            assertEquals(1, PicacgSpeedTester.probeCalls.get())
        } finally {
            SpeedTester.releaseProbe.countDown()
        }
    }

    @Test
    fun `stale generation callback is discarded by the production coordinator`() {
        RuntimeNetworkGate.setOnline(true)
        val readerPage = eu.kanade.tachiyomi.ui.reader.model.ReaderPage()
        val coordinator = ImageAttemptCoordinator()
        try {
            val attempt = PageAttemptScope(readerPage, generation = 7, coordinator = coordinator)
            RuntimeImageRecovery.retryVisiblePageAfterAttempt(
                RuntimeRecoveryPolicy.Platform.MANWA,
                previousSource = "old-image.test",
                attempt = attempt,
            )
            readerPage.generation.set(8)
            RouteManager.imgRewriteTarget = "new-image.test"
            assertNotNull(coordinator.watchdogTask)
            coordinator.watchdogTask!!.run()
            assertEquals(0, readerPage.chapter.pageLoader!!.retryCalls.get())
        } finally {
            coordinator.close()
        }
    }

    private fun waitUntil(timeoutMs: Long = 5_000L, predicate: () -> Boolean): Boolean {
        val deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMs)
        while (System.nanoTime() < deadline) {
            if (predicate()) return true
            Thread.sleep(10)
        }
        return predicate()
    }
}
